import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import 'package:table_calendar/table_calendar.dart';import 'package:zan/Core/Utils/Extensions/localizations_extension.dart';import '../../../../../../Config/Assets/image_svg.dart';import '../../../../../../Core/Resources/app_colors.dart';import '../../../../../../Core/Resources/app_fonts.dart';import '../../../../../../Core/Utils/Extensions/widget_extension.dart';import '../../../../../../Core/Utils/Widget/Images/build_image.dart';import '../../../../../../Core/Utils/Widget/custom_scaffold_messenger.dart';import '../Cubit/CarpenterService/carpenter_service_cubit.dart';import 'build_button_carpenter_service.dart';class CalendarScreen extends StatelessWidget {  const CalendarScreen({super.key});  @override  Widget build(BuildContext context) {    final watch= context.watch<CarpenterServiceCubit>() ;    final read= context.read<CarpenterServiceCubit>() ;    final local= context.local ;    return [      SliverToBoxAdapter(        child:  Column(          crossAxisAlignment: CrossAxisAlignment.start,          children: [            TableCalendar(              focusedDay: read.focusDay,              firstDay: read.firstDay,              lastDay: read.lastDay,              calendarFormat: CalendarFormat.month,              startingDayOfWeek: StartingDayOfWeek.saturday,              selectedDayPredicate: (day) => isSameDay(watch.state.selectedDay, day),              onDaySelected: (selectedDay, focusedDay) =>read.onDaySelected(selectedDay, focusedDay),              headerVisible: true,              daysOfWeekStyle: DaysOfWeekStyle(                  weekdayStyle: AppTextStyles.bodySmallBold                      .copyWith(color: AppColors.primaryColor),                  weekendStyle: AppTextStyles.bodySmallBold                      .copyWith(color: AppColors.primaryColor)),              calendarStyle: CalendarStyle(                selectedDecoration: BoxDecoration(                  color: AppColors.primaryColor,                  shape: BoxShape.circle,                ),                todayDecoration: BoxDecoration(                  color: AppColors.secondaryColor,                  shape: BoxShape.circle,                ),                defaultTextStyle: AppTextStyles.bodySmallBold                    .copyWith(color: AppColors.textColorBlack),                weekendTextStyle: AppTextStyles.bodySmallBold                    .copyWith(color: AppColors.textColorBlack),              ),              headerStyle: HeaderStyle(                titleTextStyle: AppTextStyles.h3Bold,                formatButtonVisible: false,                rightChevronIcon: BuildImageAssets(svg: AppImagesSvg.rightIcons,),               leftChevronIcon: BuildImageAssets(svg: AppImagesSvg.leftIcon,),              ),            ),            20.verticalSpace,            // Pick Time Text            Text(              local.PickTime,              style:  AppTextStyles.h6Medium.copyWith(color: AppColors.grayscale70),            ),            10.verticalSpace,            // Wrap(            //   children: read.timePeriods.map((period) {            //     return Padding(            //       padding: const EdgeInsets.symmetric(horizontal: 8).r,            //       child: ChoiceChip(            //        showCheckmark: false,            //         label: Text(period),            //         selected: watch.state.selectedTimePeriod == period,            //         onSelected: (_)=>read.onTimePeriodSelected(period),            //         selectedColor: AppColors.primaryColor,            //         backgroundColor: AppColors.grayscale10,            //         labelStyle:  AppTextStyles.bodyLargeBold.copyWith(color: watch.state.selectedTimePeriod == period            //             ? AppColors.textColorWhite : AppColors.textColorBlack)            //       ),            //     );            //   }).toList(),            // ),            //            // 15.verticalSpace,            Wrap(              spacing: 10.w,              children:  read.times.map((time) {                return ChoiceChip(                    showCheckmark: false,                  label: Text(time),                  selected: watch.state.selectedTime == time,                  onSelected: (_) => read.onTimeSelected(time),                  selectedColor: AppColors.primaryColor,                  backgroundColor: AppColors.grayscale10,                  labelStyle:AppTextStyles.bodyLargeSemiBold.copyWith(color:watch.state.selectedTime == time ? AppColors.textColorWhite : AppColors.textColorBlack)                );              }).toList(),            ),          ],        ),      ),      BuildButtonCarpenterService(        onPressed: () {          if (read.state.selectedDay == null) {            showCustomSnackBar(context, "Please Enter selected Day", SnackBarType.info);          }          else if (read.state.selectedTime.isEmpty ){            showCustomSnackBar(context, "Please Enter Selected Time", SnackBarType.info);          }          // else if (read.state.selectedTimePeriod.isEmpty ){          //   showCustomSnackBar(context, "Please Enter Selected Time Period", SnackBarType.info);          // }          else          {            read.changeScreen(Container());          }        },        text: local.Proceed,      )    ].styledAppPages(withPadding: true, withScroll: true);  }}